public async Task CheckAndGrantBadgesAsync(Guid userId)
{
    var user = await _userRepo.GetByIdAsync(userId);
    var allBadges = await _badgeRepo.GetAll().ToListAsync();
    var earnedBadgeIds = await _userBadgeRepo
        .GetWhere(ub => ub.AppUserId == userId)
        .Select(ub => ub.BadgeId).ToListAsync();

    foreach (var badge in allBadges.Where(b => !earnedBadgeIds.Contains(b.Id)))
    {
        bool earned = badge.BadgeType switch
        {
            BadgeType.Level    => user.GeneralLevel >= badge.RequiredValue,
            BadgeType.Streak   => user.CurrentStreak >= badge.RequiredValue,
            BadgeType.TaskCount => user.TotalTasksCompleted >= badge.RequiredValue,
            _ => false
        };
        if (earned)
        {
            await _userBadgeRepo.AddAsync(new UserBadge
            {
                AppUserId = userId,
                BadgeId = badge.Id,
                EarnedAt = DateTime.UtcNow
            });
            await _notifService.SendNotificationAsync(
                userId,
                "Yeni Rozet! 🏅",
                $"'{badge.Name}' rozetini kazandın!",
                "BadgeEarned");
        }
    }
    await _userBadgeRepo.SaveAsync();
}

