public class SmtpEmailService : IEmailService
{
    private readonly IConfiguration _config;
    public SmtpEmailService(IConfiguration config) => _config = config;

    private SmtpClient CreateClient()
    {
        var host = _config["EmailSettings:Host"] ?? "smtp.gmail.com";
        var port = int.Parse(_config["EmailSettings:Port"] ?? "587");
        var user = _config["EmailSettings:Username"] ?? Environment.GetEnvironmentVariable("SMTP_USER");
        var pass = _config["EmailSettings:Password"] ?? Environment.GetEnvironmentVariable("SMTP_PASS");
        return new SmtpClient(host, port) { Credentials = new NetworkCredential(user, pass), EnableSsl = true };
    }

    public async Task SendEmailVerificationAsync(string email, string name, string token)
    {
        var url = $"{_config["FrontendUrl"]}/verify-email?token={token}";
        var body = $"Merhaba {name},<br><br>Email doğrulamak için <a href='{url}'>buraya tıklayın</a>.<br>Link 24 saat geçerlidir.";
        using var client = CreateClient();
        var msg = new MailMessage(_config["EmailSettings:FromEmail"]!, email, "LifeQuest — Email Doğrulama", body) { IsBodyHtml = true };
        await client.SendMailAsync(msg);
    }

    public async Task SendPasswordResetAsync(string email, string name, string token)
    {
        var url = $"{_config["FrontendUrl"]}/reset-password?token={token}";
        var body = $"Merhaba {name},<br><br>Şifre sıfırlamak için <a href='{url}'>buraya tıklayın</a>.<br>Link 1 saat geçerlidir.";
        using var client = CreateClient();
        var msg = new MailMessage(_config["EmailSettings:FromEmail"]!, email, "LifeQuest — Şifre Sıfırlama", body) { IsBodyHtml = true };
        await client.SendMailAsync(msg);
    }

    public Task SendWeeklyReportAsync(string email, string name, WeeklyReportEmailDto report)
    {
