        var body = $"Merhaba {name},<br><br>Bu hafta <b>{report.CompletedCount}</b> görev tamamladın! Geçen haftaya göre %{report.ChangePercent:0} {sign}.<br>En verimli gün: {report.BestDay}.";
        using var client = CreateClient();
        var msg = new MailMessage(_config["EmailSettings:FromEmail"]!, email, "LifeQuest — Haftalık Özet", body) { IsBodyHtml = true };
        return client.SendMailAsync(msg);
    }
