import * as signalR from '@microsoft/signalr';
import { useEffect, useRef, useCallback } from 'react';
import { getAccessToken } from '../api/axiosClient';

export const useSignalR = (onNotification, onProactiveMessage) => {
  const connectionRef = useRef(null);

  const startConnection = useCallback(async () => {
    const token = getAccessToken();
    if (!token) return;

    const connection = new signalR.HubConnectionBuilder()
      .withUrl(
        `${import.meta.env.VITE_API_BASE_URL?.replace('/api', '') || 'http://localhost:5020'}/hubs/notification`,
        { accessTokenFactory: () => getAccessToken() }
      )
      .withAutomaticReconnect([0, 2000, 5000, 10000])
      .configureLogging(signalR.LogLevel.Warning)
      .build();

    connection.on('ReceiveNotification', (title, message, type) => {
      onNotification?.({ title, message, type });
    });
    connection.on('ReceiveProactiveMessage', (message) => {
      onProactiveMessage?.({ message });
      window.dispatchEvent(new CustomEvent('openChatBot', { detail: { message } }));
    });
    connection.onreconnecting(() => console.warn('SignalR: Yeniden bağlanıyor...'));
    connection.onreconnected(() => console.info('SignalR: Bağlantı yenilendi.'));

    try {
      await connection.start();
      connectionRef.current = connection;
    } catch (err) {
      console.error('SignalR bağlantı hatası:', err);
    }
    return () => connection.stop();
  }, [onNotification, onProactiveMessage]);

  useEffect(() => {
    const cleanup = startConnection();
    return () => { cleanup?.then(fn => fn?.()); };
  }, [startConnection]);

  return connectionRef;
};

